test('HTTP OAuth boundary preserves cookie/location and disables caching without listening', async () => {
  const h = harness(); const instance = createApp({ oauth: h.oauth });
  const req = Readable.from([]); Object.assign(req, { method: 'GET', url: '/oauth/bot/start', headers: {} });
  const res = { writeHead(status, headers) { this.status = status; this.headers = headers; }, end(body) { this.body = body; } };
  await instance.handler(req, res);
  assert.equal(res.status, 302); assert.equal(res.headers['cache-control'], 'no-store');
  assert.match(res.headers['set-cookie'], /HttpOnly/); assert.match(res.headers.location, /^https:\/\/id.twitch.tv/);
  assert.equal(res.headers['content-length'], 0);
  assert.equal((await createApp().dispatch({ method: 'GET', path: '/oauth/bot/start' })).status, 503);
  assert.equal((await instance.dispatch({ method: 'GET', path: '/auth/callback' })).status, 404);
});
